// Gate 1 — authenticate the caller.
// MunshiJi signs every dispatch with X-Munshiji-Token (N8N_WEBHOOK_TOKEN in its .env).
// Set the same value in this workflow's MUNSHIJI_TOKEN variable, or leave it blank locally.
const expected = $env.MUNSHIJI_TOKEN || '';
const incoming = $json.headers?.['x-munshiji-token'] || '';

if (expected && incoming !== expected) {
  throw new Error('unauthorised: X-Munshiji-Token did not match');
}

const body = $json.body ?? {};

// Gate 2 — never act on something the merchant did not approve. MunshiJi already enforces this
// in its own state machine; this is the second lock, on the other side of the wire.
if (body?.meta?.approved !== true) {
  throw new Error('refused: action is not marked approved');
}

return [{ json: body }];

// One item per recipient, so downstream send nodes batch naturally.
// Actions with no customer recipients (restock, follow-up) emit a single item instead.
const payload = $json;
const targets = Array.isArray(payload.targets) ? payload.targets : [];

const envelope = {
  action_id: payload.action_id,
  merchant_id: payload.merchant_id,
  shop_name: payload.merchant?.shop_name ?? '',
  tool: payload.tool,
  language: payload.language ?? 'hi',
  idempotency_key: payload.idempotency_key,
};

if (targets.length === 0) {
  return [{ json: { ...envelope, kind: 'no_recipients', params: payload.params ?? {}, summary: payload.summary ?? {} } }];
}

// Undeliverable rows are already filtered out by MunshiJi, but never trust that twice.
return targets
  .filter((t) => t && t.deliverable !== false && t.phone)
  .map((t, index) => ({
    json: {
      ...envelope,
      kind: 'message',
      index,
      customer_id: t.customer_id,
      name: t.name,
      phone: t.phone,
      text: t.message || t.message_hi || t.message_en || '',
      amount_paise: t.amount_paise ?? null,
      amount_display: t.amount_display ?? null,
      khata_entry_id: t.khata_entry_id ?? null,
      days_overdue: t.days_overdue ?? null,
    },
  }));

// Aggregate into the shape MunshiJi's n8n client parses.
// Preferred response: { ok, delivered, failed, id, results: [{customer_id, ok}] }
// Including `results` matters: with it, only the khata rows that genuinely went out get their
// reminder counter bumped. Without it MunshiJi credits the first `delivered` targets in order.
const items = $input.all();
const results = [];
let delivered = 0;
let failed = 0;

for (const item of items) {
  const data = item.json ?? {};
  if (data.kind === 'no_recipients') {
    return [{ json: { ok: true, delivered: 0, failed: 0, id: data.action_id, results: [] } }];
  }
  // A disabled send node passes the recipient straight through, which counts as delivered in a
  // dry run; a live send surfaces provider errors under `error`.
  const ok = !data.error && !(data.errors && data.errors.length);
  if (ok) delivered += 1; else failed += 1;
  results.push({ customer_id: data.customer_id ?? null, ok });
}

return [{
  json: {
    ok: failed === 0,
    delivered,
    failed,
    id: items[0]?.json?.idempotency_key ?? null,
    results,
  },
}];
